INSERT IGNORE INTO feed_task_account (
  tenant_id, task_id, account_id, account_phone_snapshot, send_status,
  retry_num, retry_max, created_at, updated_at
) VALUES (
  #{tenantId}, #{taskId}, #{accountId}, #{accountPhoneSnapshot}, #{sendStatus},
  #{retryNum}, #{retryMax}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
  FROM feed_task_account
 WHERE task_id = #{taskId}

   AND account_phone_snapshot LIKE CONCAT('%', #{accountPhone}, '%')

 ORDER BY id DESC
 LIMIT #{offset}, #{limit}

SELECT 
  FROM feed_task_account
 WHERE task_id = #{taskId}
   AND send_status IN ('pending', 'retrying')
 ORDER BY id ASC
 LIMIT #{limit}

mapper.update:
UPDATE feed_task_account
   SET send_status = 'sending',
       retry_num = retry_num + 1,
       command_id = #{commandId},
       round_no = #{roundNo},
       send_at = CASE WHEN send_at IS NULL THEN #{sendAt} ELSE send_at END,
       updated_at = #{sendAt}
 WHERE id = #{id}
   AND send_status = #{expectedStatus}
